"""Read-only adaptive record custody and selected-set planning. No quality execution.

inspect --record FILE; plan-set --selection FILE. Python 3.10+ standard library;
PyYAML is used only for complete descriptor/frontmatter identity interpretation.
"""
import argparse
import importlib.util
import json
import os
from pathlib import Path
import re
import sys

sys.dont_write_bytecode = True
PACKAGE = Path(__file__).resolve().parents[1]
_spec = importlib.util.spec_from_file_location('adaptive_binding_runtime', PACKAGE / 'assets/adaptive-runtime/check_project_binding.py')
runtime = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(runtime)
import authoring

VERSIONS = {'project-evidence-v1', 'adaptation-proposal-v1', 'adaptation-selection-v1',
            'set-authoring-v1', 'set-validation-request-v1', 'adaptive-skill-v1',
            'project-binding-v1', 'adaptive-observation-v1', 'binding-observation-v1'}


def need(condition, message):
    if not condition:
        raise ValueError(message)


def validate_shape(value, schema, document, location='$'):
    """Evaluate only the Draft 2020-12 vocabulary used by shipped closed schemas.

    This is not an arbitrary external JSON Schema engine; remote refs never load.
    """
    if '$ref' in schema:
        reference = schema['$ref']
        if reference.startswith('adaptive-common.schema.json#/$defs/'):
            document = runtime.strict_json((PACKAGE / 'schemas/adaptive-common.schema.json').read_bytes())
            reference = reference[len('adaptive-common.schema.json'):]
        need(reference.startswith('#/$defs/'), 'unsupported schema reference')
        return validate_shape(value, document['$defs'][reference[8:]], document, location)
    if 'anyOf' in schema:
        for option in schema['anyOf']:
            try:
                validate_shape(value, option, document, location)
                return
            except ValueError:
                pass
        raise ValueError(location + ': no supported type alternative')
    if 'const' in schema:
        need(type(value) is type(schema['const']) and value == schema['const'], location + ': wrong constant/version')
    if 'enum' in schema:
        need(value in schema['enum'], location + ': unknown enum')
    kind = schema.get('type')
    types = {'object': dict, 'array': list, 'string': str, 'integer': int, 'boolean': bool, 'null': type(None)}
    if kind:
        need(type(value) is types[kind], location + ': wrong type')
    if kind == 'object':
        need(set(schema['required']) <= set(value) and set(value) <= set(schema['properties']), location + ': missing/extra fields')
        for key, child in value.items():
            validate_shape(child, schema['properties'][key], document, location + '.' + key)
    elif kind == 'array':
        need(len(value) >= schema.get('minItems', 0), location + ': too few items')
        if schema.get('uniqueItems'):
            need(len({runtime.compact(x) for x in value}) == len(value), location + ': duplicate items')
        for index, child in enumerate(value):
            validate_shape(child, schema['items'], document, location + '[' + str(index) + ']')
    elif kind == 'string':
        need(len(value) >= schema.get('minLength', 0) and len(value) <= schema.get('maxLength', len(value)), location + ': invalid length')
        if 'pattern' in schema:
            need(re.search(schema['pattern'], value) is not None, location + ': invalid string')
    elif kind == 'integer':
        need(value >= schema.get('minimum', value), location + ': integer below minimum')


def shape(value, version=None):
    need(isinstance(value, dict), 'record must be an object')
    version = version or value.get('schema_version')
    need(version in VERSIONS, 'unknown adaptive schema version')
    schema = runtime.strict_json((PACKAGE / 'schemas' / (version + '.schema.json')).read_bytes())
    validate_shape(value, schema, schema)
    return value


def indexed(rows, key='id'):
    result = {row[key]: row for row in rows}
    need(len(result) == len(rows), 'duplicate ' + key)
    return result


def topology(members):
    pending = {key: set(row['depends_on']) for key, row in members.items()}
    need(all(deps <= set(members) for deps in pending.values()), 'missing dependency/selection closure')
    result = []
    while pending:
        ready = sorted(key for key, deps in pending.items() if not deps)
        need(bool(ready), 'dependency cycle')
        key = ready[0]
        result.append(key)
        pending.pop(key)
        for deps in pending.values():
            deps.discard(key)
    return result


def aggregate(members):
    statuses = [row['status'] for row in members]
    if statuses and all(s == 'RETAINED' for s in statuses):
        return 'NO_CHANGE'

